// Turn the command output into fields a human can read in the run log.
const raw = $input.first().json;
let summary = {};
try { summary = JSON.parse(raw.stdout || '{}'); } catch (e) { summary = { parseError: String(e), stdout: raw.stdout }; }
const failed = (summary.checks || []).filter(c => c.status === 'fail');
return [{ json: {
  trustworthy: summary.trustworthy === true,
  verdict: summary.verdict || 'UNKNOWN',
  exitCode: raw.exitCode,
  destination: summary.destination,
  rowsInSheet: summary.counts?.sheet ?? null,
  rowsInExport: summary.counts?.truth ?? null,
  failures: failed.map(c => `${c.id}: ${c.headline}`),
} }];

// Where a Slack, email or ticket node goes. Kept as code so this workflow
// imports and runs without any credentials configured.
const j = $input.first().json;
console.log('ALERT — ' + j.verdict);
for (const f of j.failures) console.log('  · ' + f);
return [{ json: { alerted: true, ...j } }];
